#pragma once
// =============================================================================
// SRAT-20 — Staggered Residual-Adaptive Transport
// Absolute canonical C++20 engine
// Aligns with GR-21 / Chimera / Monsters Ink seal: S_H = S_solv ∧ R_H
// 3-slot hazard pointers • residual certificates • self-tuning genome
//
// PATCH 2026-10-15 — audit-driven, against PROGRESS_ARGUMENT.md.
// Findings were verified against this file's prior revision; each fix below
// cites its finding. See PATCH_NOTES.md for the full audit record.
//
//  [P1] LIVELOCK FIX — tail-helping is now UNCONDITIONAL (structural).
//       Conditioning the tail swing on residual validity wedged the whole
//       structure: an epoch-invalidated node sitting at tail->next with
//       head==tail made BOTH enqueue and dequeue spin forever (neither
//       helped it, neither unlinked it). Pointer-helping cannot return
//       data, so the residual gate does not belong here. Validity is still
//       enforced where it matters: at publish (enqueue gate + pre-CAS
//       recheck) and at return (dequeue final check).
//  [P2] UAF FIX — packets are hazard-protected (slot 2) and retired via the
//       reclamation path; never inline-deleted. The old dequeue did
//       `delete data` while a concurrent dequeuer could still hold the raw
//       packet pointer (nodes were HP-protected; packets were not).
//  [P3] FENCE FIX — protect() stores the hazard pointer with seq_cst and
//       scan() opens with a seq_cst fence. Release/acquire alone does not
//       establish "never reclaimed while referenced" under strict C++20:
//       there is no happens-before edge from a protector's HP store to a
//       scanner's HP load in the critical interleaving.
//  [P4] TUNER FIX — fitness() now depends on spin_limit (spin-cost term).
//       Previously fitness was genome-independent, so the mutation CAS
//       could never observe an improvement and the self-tuning genome was
//       dead code. (damping is reserved for future backoff policy.)
//  [P5] PRE-CAS RECHECK — enqueue re-verifies residual validity immediately
//       before the link CAS; the epoch may have advanced since the Stage-1
//       gate. Dequeue's final check remains authoritative.
// =============================================================================

#include <atomic>
#include <cstdint>
#include <cmath>
#include <optional>
#include <thread>
#include <chrono>
#include <functional>
#include <vector>
#include <new>
#include <utility>

namespace srat20 {

// ─────────────────────────────────────────────────────────────────────────────
// 3-slot C++20 Hazard Pointers
// ─────────────────────────────────────────────────────────────────────────────
namespace hp {

inline constexpr unsigned MaxHP = 3;
inline constexpr size_t  RetireThreshold = 6;

struct Record {
    std::atomic<void*> slots[MaxHP]{};
    std::atomic<Record*> next{nullptr};
    std::atomic<bool> active{false};
};

// [P2] Retired items carry their own deleter: the retired list mixes Node*
// and OmniPacket*, and a single deleter cannot serve both types.
struct RetiredItem {
    void*  ptr;
    void (*del)(void*);
};

inline std::atomic<Record*> head_rec{nullptr};
inline thread_local Record* tls = nullptr;
inline thread_local std::vector<RetiredItem> retired;

inline Record* acquire() {
    if (tls) [[likely]] return tls;

    for (Record* r = head_rec.load(std::memory_order_acquire);
         r; r = r->next.load(std::memory_order_acquire)) {
        bool exp = false;
        if (r->active.compare_exchange_strong(exp, true,
                std::memory_order_acquire, std::memory_order_relaxed)) {
            tls = r;
            return r;
        }
    }

    auto* r = new Record();
    r->active.store(true, std::memory_order_relaxed);
    Record* old = head_rec.load(std::memory_order_relaxed);
    do {
        r->next.store(old, std::memory_order_relaxed);
    } while (!head_rec.compare_exchange_weak(old, r,
                std::memory_order_release, std::memory_order_relaxed));
    tls = r;
    return r;
}

template <typename AtomicPtr>
auto protect(AtomicPtr& src, unsigned slot = 0) {
    if (slot >= MaxHP) [[unlikely]] slot = 0;
    Record* rec = acquire();
    using Ptr = typename AtomicPtr::value_type;
    Ptr p;
    do {
        p = src.load(std::memory_order_acquire);
        // [P3] seq_cst: pairs with the seq_cst fence at scan() open so a
        // scanner is guaranteed to observe a hazard pointer stored before
        // the protector's confirming re-read.
        rec->slots[slot].store(static_cast<void*>(p), std::memory_order_seq_cst);
    } while (p != src.load(std::memory_order_acquire));
    return p;
}

inline void clear(unsigned slot = 0) noexcept {
    if (tls && slot < MaxHP) [[likely]]
        tls->slots[slot].store(nullptr, std::memory_order_release);
}

inline void clear_all() noexcept {
    if (tls) [[likely]]
        for (unsigned i = 0; i < MaxHP; ++i)
            tls->slots[i].store(nullptr, std::memory_order_release);
}

inline void scan() {
    // [P3] Interposed fence: sits between every unlink-CAS (release,
    // program-order-before retire()) and the hazard-pointer loads below,
    // closing the visibility gap that release/acquire alone leaves open.
    std::atomic_thread_fence(std::memory_order_seq_cst);

    std::vector<void*> haz;
    haz.reserve(64);
    for (Record* r = head_rec.load(std::memory_order_acquire);
         r; r = r->next.load(std::memory_order_acquire)) {
        for (unsigned i = 0; i < MaxHP; ++i)
            if (void* p = r->slots[i].load(std::memory_order_acquire))
                haz.push_back(p);
    }
    auto it = retired.begin();
    while (it != retired.end()) {
        bool keep = false;
        for (void* h : haz) if (it->ptr == h) { keep = true; break; }
        if (keep) ++it;
        else { it->del(it->ptr); it = retired.erase(it); }
    }
}

template <typename T>
inline void retire(T* p) {
    if (!p) [[unlikely]] return;
    retired.push_back({static_cast<void*>(p),
                       [](void* x){ delete static_cast<T*>(x); }});
    if (retired.size() >= RetireThreshold) scan();
}

inline void flush() { scan(); }

} // namespace hp

// ─────────────────────────────────────────────────────────────────────────────
// Packet — residual certificate is first-class
// ─────────────────────────────────────────────────────────────────────────────
struct alignas(32) OmniPacket {
    uint32_t c = 0, m = 0, p = 0, q = 0;       // GR-21 resource vector
    float    x = 0, y = 0, z = 0, psi = 0;      // kinematics
    uint64_t digest = 0;

    float    residual_H = 0.0f;
    float    epsilon_H  = 0.01f;
    uint64_t residual_epoch = 0;

    bool residual_ok(uint64_t epoch) const noexcept {
        return residual_epoch + 1 >= epoch &&
               std::abs(residual_H) <= epsilon_H;
    }
    bool resources_ok(const OmniPacket& ceil) const noexcept {
        return c <= ceil.c && m <= ceil.m && p <= ceil.p && q <= ceil.q;
    }
    uint64_t bind(uint64_t prev) const noexcept {
        return prev ^ (uint64_t(c) * p) ^ uint64_t(psi * 1e4f)
                    ^ uint64_t(residual_H * 1e6f);
    }
};

// ─────────────────────────────────────────────────────────────────────────────
// Execution Genome — self-tuning under residual pressure
// ─────────────────────────────────────────────────────────────────────────────
struct alignas(16) Genome {
    uint32_t spin_limit = 64;
    float    damping    = 0.10f;   // reserved: future backoff policy
    uint64_t generation = 1;

    double fitness(double ops, double lat_ns, double thermal,
                   float residual_pressure) const noexcept {
        if (lat_ns <= 0.0 || thermal <= 0.0) return 0.0;
        // [P4] Spin-cost term: fitness must depend on the genome's mutable
        // fields, otherwise no mutation can ever observe an improvement and
        // the tuner is dead code (as it was). Higher spin_limit burns more
        // CPU per contended op, so the tuner converges toward the cheapest
        // spin the measured interval justifies. Limitation: candidates are
        // scored on the same measured interval (no A/B trial), so this is
        // cost-driven convergence, not measured exploration.
        const double spin_cost = 1.0 + double(spin_limit) / 1024.0;
        return (ops / (lat_ns * thermal)) / ((1.0 + residual_pressure) * spin_cost);
    }
};

// ─────────────────────────────────────────────────────────────────────────────
// SRAT-20 Engine
// Stages: residual+resource gate → digest bind → HP enqueue → structural
//         helping → self-measured fitness mutation → HP retirement
//
// Residual-gate placement (patched): the gate authorizes PUBLISHING a packet
// (enqueue Stage 1 + pre-CAS recheck) and RETURNING a packet (dequeue final
// check). Pointer-helping (tail swings) is structural and unconditional — it
// cannot leak data, and conditioning it on validity caused a permanent wedge.
// ─────────────────────────────────────────────────────────────────────────────
class SRAT20 {
    struct Node {
        std::atomic<OmniPacket*> data{nullptr};
        std::atomic<Node*> next{nullptr};
    };

    std::atomic<Node*>    head;
    std::atomic<Node*>    tail;
    OmniPacket            ceiling_;
    std::atomic<Genome>   genome_;
    std::atomic<uint64_t> epoch_{0};

    std::atomic<uint64_t> ops_{0};
    std::atomic<uint64_t> latency_sum_{0};
    std::atomic<uint64_t> thermal_sum_{0};
    std::atomic<uint64_t> last_evolve_ops_{0};
    static constexpr uint64_t EvolveEvery = 4096;

public:
    SRAT20(OmniPacket ceiling, Genome g) : ceiling_(ceiling) {
        Node* d = new Node;
        head.store(d, std::memory_order_relaxed);
        tail.store(d, std::memory_order_relaxed);
        genome_.store(g, std::memory_order_relaxed);
    }

    ~SRAT20() {
        while (dequeue()) {}
        delete head.load(std::memory_order_relaxed);
        hp::flush();
    }

    uint64_t epoch() const noexcept {
        return epoch_.load(std::memory_order_acquire);
    }
    void advance_epoch() noexcept {
        epoch_.fetch_add(1, std::memory_order_acq_rel);
    }
    Genome genome() const noexcept {
        return genome_.load(std::memory_order_acquire);
    }

    // Stage 5 — self-tuning mutation (cannot bypass residual seal)
    void maybe_evolve(float residual_pressure) {
        uint64_t cur = ops_.load(std::memory_order_relaxed);
        uint64_t last = last_evolve_ops_.load(std::memory_order_relaxed);
        if (cur - last < EvolveEvery) return;

        double interval = double(cur - last);
        double avg_lat  = interval > 0
            ? double(latency_sum_.exchange(0, std::memory_order_relaxed)) / interval
            : 1.0;
        double thermal  = 1.0 + 1e-4 * double(
            thermal_sum_.exchange(0, std::memory_order_relaxed));

        Genome cur_g = genome_.load(std::memory_order_relaxed);
        double cur_f = cur_g.fitness(interval, avg_lat, thermal, residual_pressure);

        Genome mut = cur_g;
        mut.generation = cur_g.generation + 1;
        mut.spin_limit = (cur_g.spin_limit < 256) ? cur_g.spin_limit * 2 : 32;
        mut.damping   *= 0.95f;

        if (mut.fitness(interval, avg_lat, thermal, residual_pressure) > cur_f) {
            if (genome_.compare_exchange_strong(cur_g, mut,
                    std::memory_order_release, std::memory_order_relaxed)) {
                last_evolve_ops_.store(cur, std::memory_order_relaxed);
            }
        } else {
            last_evolve_ops_.store(cur, std::memory_order_relaxed);
        }
    }

    // Stages 1–3 + 4 + 6
    bool enqueue(OmniPacket pkt) {
        auto t0 = std::chrono::steady_clock::now();

        // Stage 1 — fail-closed residual + resource gate (GR-21 seal)
        if (!pkt.resources_ok(ceiling_) || !pkt.residual_ok(epoch()))
            return false;

        // Stage 2 — cryptographic binding (includes residual)
        pkt.digest = pkt.bind(pkt.digest);

        Node* node = new Node;
        node->data.store(new OmniPacket(std::move(pkt)), std::memory_order_relaxed);

        Genome g = genome_.load(std::memory_order_relaxed);
        uint32_t spins = 0;

        while (true) {
            // Stage 3 — HP-protected CAS (slot 0 = tail)
            Node* last = hp::protect(tail, 0);
            Node* next = last->next.load(std::memory_order_acquire);

            if (last != tail.load(std::memory_order_acquire)) {
                hp::clear_all();
                continue;
            }

            if (next == nullptr) {
                // [P5] Recheck validity immediately before the link CAS: the
                // epoch may have advanced since the Stage-1 gate. (Dequeue's
                // final check remains authoritative; this narrows the window
                // in which an invalid node gets linked and must be cleaned.)
                OmniPacket* pend = node->data.load(std::memory_order_relaxed);
                if (!pend->residual_ok(epoch())) {
                    delete pend;
                    delete node;
                    hp::clear_all();
                    return false;
                }
                if (last->next.compare_exchange_weak(next, node,
                        std::memory_order_release, std::memory_order_relaxed)) {
                    tail.compare_exchange_strong(last, node,
                        std::memory_order_release, std::memory_order_relaxed);
                    hp::clear_all();

                    ops_.fetch_add(1, std::memory_order_relaxed);
                    auto ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
                                  std::chrono::steady_clock::now() - t0).count();
                    latency_sum_.fetch_add(ns, std::memory_order_relaxed);
                    thermal_sum_.fetch_add(1, std::memory_order_relaxed);
                    maybe_evolve(pend->residual_H);
                    return true;
                }
            } else {
                // Stage 4 — structural tail helping. [P1] UNCONDITIONAL:
                // advancing the tail pointer cannot return data, so the
                // residual gate does not apply here. The old code refused to
                // help an invalid node, which wedged the queue permanently
                // when an epoch advance invalidated the tail node (both
                // enqueue and dequeue spun forever). `next` is used only as
                // a pointer value — never dereferenced — so no hazard slot
                // is needed for the swing itself.
                tail.compare_exchange_strong(last, next,
                    std::memory_order_release, std::memory_order_relaxed);
            }
            hp::clear_all();

            if (++spins > g.spin_limit) {
                std::this_thread::yield();
                spins = 0;
            }
        }
    }

    std::optional<OmniPacket> dequeue() {
        auto t0 = std::chrono::steady_clock::now();

        while (true) {
            Node* first = hp::protect(head, 0);          // slot 0
            Node* last  = tail.load(std::memory_order_acquire);
            Node* next  = first->next.load(std::memory_order_acquire);

            if (first != head.load(std::memory_order_acquire)) {
                hp::clear_all();
                continue;
            }

            if (first == last) {
                if (next == nullptr) {
                    hp::clear_all();
                    return std::nullopt;
                }
                // [P1] Unconditional structural help (see enqueue Stage 4).
                // `next` is a pointer value only — no dereference, no HP.
                tail.compare_exchange_strong(last, next,
                    std::memory_order_release, std::memory_order_relaxed);
                hp::clear_all();
            } else {
                Node* prot = hp::protect(first->next, 1); // slot 1
                if (prot != next) {
                    hp::clear_all();
                    continue;
                }

                // [P2] Hazard-protect the packet itself (slot 2). The node
                // is protected, but the old code deleted the packet inline
                // while a concurrent dequeuer could still hold the raw
                // pointer — a use-after-free the old Claim A did not cover.
                OmniPacket* data = hp::protect(next->data, 2);
                if (!data) {
                    hp::clear_all();
                    continue;
                }

                // Final residual check at linearization (seal re-assertion)
                if (!data->residual_ok(epoch())) {
                    if (head.compare_exchange_weak(first, next,
                            std::memory_order_release, std::memory_order_relaxed)) {
                        next->data.store(nullptr, std::memory_order_relaxed);
                        hp::retire<OmniPacket>(data);
                        hp::retire<Node>(first);
                    }
                    hp::clear_all();
                    continue;
                }

                if (head.compare_exchange_weak(first, next,
                        std::memory_order_release, std::memory_order_relaxed)) {
                    OmniPacket val = std::move(*data);
                    next->data.store(nullptr, std::memory_order_relaxed);
                    hp::retire<OmniPacket>(data);
                    hp::retire<Node>(first);
                    hp::clear_all();

                    ops_.fetch_add(1, std::memory_order_relaxed);
                    auto ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
                                  std::chrono::steady_clock::now() - t0).count();
                    latency_sum_.fetch_add(ns, std::memory_order_relaxed);
                    thermal_sum_.fetch_add(1, std::memory_order_relaxed);
                    maybe_evolve(val.residual_H);
                    return val;
                }
                hp::clear_all();
            }
        }
    }
};

} // namespace srat20

#!/usr/bin/env python3
"""build_hoard.py - build Niffler's Hoard (castle page) from Niffler's Pouch.

Usage: python3 build_hoard.py [pouch.md] [out.html]
Defaults: nifflers-pouch.md -> nifflers-hoard.html (next to this script).
Python stdlib only. Self-verifies; prints [PASS]/[FAIL] lines and exits 1 on any fail.
"""
import base64, html, os, re, sys
from urllib.parse import urlparse

FAVICON_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'icon', 'hoard-favicon.png')


def favicon_tag():
    with open(FAVICON_PATH, 'rb') as f:
        data = f.read()
    assert data[:8] == b'\x89PNG\r\n\x1a\n', 'favicon is not a PNG: %s' % FAVICON_PATH
    return '<link rel="icon" type="image/png" href="data:image/png;base64,%s">' % base64.b64encode(data).decode('ascii')


