html{scroll-behavior:smooth;color-scheme:dark;scroll-padding-top:64px}
body{margin:0;color:var(--ink);font:400 17px/1.65 var(--sans);
 background:var(--granite),var(--basalt),radial-gradient(ellipse 80% 40% at 50% 0%,rgba(255,138,43,.12),transparent 70%),linear-gradient(180deg,#1b1916,#0d0c0b);
