 box-shadow:inset 0 0 80px rgba(0,0,0,.65),0 20px 50px rgba(0,0,0,.6);border-left:6px solid #0b0a09;border-right:6px solid #0b0a09}
.wall::after{content:"";position:absolute;left:0;right:0;bottom:0;height:16px;background:var(--knot) repeat-x center;opacity:.85}
