TOUCH_ICON_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'icon', 'apple-touch-icon-180.png')


def touch_icon_tag():
    with open(TOUCH_ICON_PATH, 'rb') as f:
        data = f.read()
    assert data[:8] == b'\x89PNG\r\n\x1a\n' and data[16:24] == (180).to_bytes(4, 'big') * 2, 'apple-touch-icon must be a 180x180 PNG'
    return '<link rel="apple-touch-icon" sizes="180x180" href="data:image/png;base64,%s">' % base64.b64encode(data).decode('ascii')


E = lambda s: html.escape(s, quote=True)
URL_RE = re.compile(r'https?://\S+')


def inline(s):
    """Escape, then render **bold** and *em*."""
    s = E(s)
    s = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', s)
    s = re.sub(r'(?<![\w*])\*(?!\s)(.+?)(?<!\s)\*(?![\w*])', r'<em>\1</em>', s)
    return s


def plain(s):
    return re.sub(r'\*\*(.+?)\*\*|\*(.+?)\*', lambda m: m.group(1) or m.group(2), s)


def roman(n):
    out = ''
    for v, r in ((1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'),
                 (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')):
        while n >= v:
            out += r; n -= v
    return out


def host(u):
    return urlparse(u).netloc


def split_top_colon(s):
    """Split 'note: attribution' at the first ': ' outside parentheses."""
    depth = 0
    for i, ch in enumerate(s):
        if ch in '([':
            depth += 1
        elif ch in ')]':
            depth = max(0, depth - 1)
        elif ch == ':' and depth == 0 and s[i + 1:i + 2] == ' ':
            return s[:i], s[i + 2:]
    return s, ''


def parse_ledger_line(line):
    body = line[2:].strip()
    m = re.match(r'([A-Z]+)\s*(.*)$', body)
    kind, rest = m.group(1), m.group(2)
    if kind == 'KNOWN' and rest.startswith('RESULT'):
        kind, rest = 'KNOWN RESULT', rest[len('RESULT'):].lstrip()
    url = ''
    um = re.search(r'\s(https?://\S+)\s*$', rest)
    if um:
        url, rest = um.group(1), rest[:um.start()]
    quote = ''
    qm = re.search(r'"([^"]*)"\s*$', rest)
    if qm:
        quote, rest = qm.group(1), rest[:qm.start()]
    note, attr = split_top_colon(rest.rstrip())
    return {'kind': kind, 'note': note.strip(), 'attr': attr.strip().rstrip(':').strip(),
            'quote': quote, 'url': url, 'raw': line}


def sections(md):
    out, cur, buf = {}, '_pre', []
    for ln in md.split('\n'):
        if ln.startswith('## '):
            out[cur] = buf; cur, buf = ln[3:].strip(), []
        else:
            buf.append(ln)
    out[cur] = buf
    return out


def find_sec(secs, prefix):
    for k, v in secs.items():
        if k.lower().startswith(prefix.lower()):
            return k, v
    return None, []


def parse(md):
    d = {}
    pre = sections(md)['_pre']
    d['title'] = next((l[2:].strip() for l in pre if l.startswith('# ')), "Niffler's Pouch")
    d['tagline'] = next((l.strip() for l in pre if l.strip() and not l.startswith('#')
                         and not l.startswith('Last updated') and not l.startswith('Master copy')), '')
    lu = re.search(r'^Last updated:\s*(.+)$', md, re.M)
    d['updated'] = lu.group(1).strip() if lu else ''
    secs = sections(md)

    _, held = find_sec(secs, 'Handed to Hermes')
    d['ledger'], d['waiting'] = [], []
    target = d['ledger']
    for ln in held:
        if ln.startswith('### ') and 'waiting' in ln.lower():
            target = d['waiting']; continue
        if ln.startswith('- '):
            target.append(parse_ledger_line(ln))

    _, ranked_lines = find_sec(secs, 'Ranked')
    ranked, cur = [], None
    for ln in ranked_lines:
        m = re.match(r'^###\s+(\d+)\s*$', ln)
        if m:
            cur = {'rank': int(m.group(1))}; ranked.append(cur); continue
        fm = re.match(r'^\*\*(.+?):\*\*\s*(.*)$', ln)
        if cur is not None and fm:
            cur[fm.group(1).strip()] = fm.group(2).strip()
    d['ranked'] = ranked

    _, disc = find_sec(secs, 'Discarded')
    d['discards'] = [l[2:].strip() for l in disc if l.startswith('- ')]
    cm = re.search(r'\*\*(\d+)\*\*', '\n'.join(disc))
    d['discard_count_stated'] = int(cm.group(1)) if cm else None
    n = 0
    for it in d['discards']:
        r = re.match(r'(\d+)(?:\s*[–-]\s*(\d+))?\.', it)
        if r:
            n = max(n, int(r.group(2) or r.group(1)))
    d['discard_count'] = n

    _, finds = find_sec(secs, 'New finds')
    d['finds_intro'] = next((l.strip() for l in finds if l.strip() and not re.match(r'^\d+\.', l)
                             and l.strip() != '---'), '')
    d['finds'] = []
    for l in finds:
        m = re.match(r'^(\d+)\.\s+\*\*(.+?)\*\*\s*[—-]\s*(.*)$', l)
        if m:
            text = m.group(3)
            um = re.search(r'\s*URL:\s*(https?://\S+)\s*$', text)
            url = um.group(1) if um else ''
            if um:
                text = text[:um.start()]
            d['finds'].append({'num': int(m.group(1)), 'title': m.group(2), 'text': text.strip(), 'url': url})

    _, tally = find_sec(secs, 'Verification tally')
    d['tally'] = []
    for l in tally:
        m = re.match(r'^-\s*(.+?):\s*\*\*(\d+)\*\*', l)
        if m:
            d['tally'].append((m.group(1).strip(), int(m.group(2))))
    return d


STATUSES = [('KNOWN RESULT', 'known'), ('CONFIRMED', 'confirmed'), ('CONTESTED', 'contested'), ('HYPOTHESIS', 'hypothesis')]


def statuses(text):
    """Status labels named in text, in fixed order, each once."""
    return [(lab, cls) for lab, cls in STATUSES if lab in text]


def badge(lab, cls):
    return '<span class="badge b-%s">%s</span>' % (cls, E(lab))


def src_link(u):
    return ('<a class="source" href="%s" target="_blank" rel="noopener noreferrer">Source &#8599; '
            '<span class="host">%s</span></a>' % (E(u), E(host(u))))


def nearby(s):
    m = re.match(r'\s*before:\s*(.*?)\s+—\s+after:\s*(.*)$', s)
    if m:
        return ('<p><span class="lbl">before:</span> %s</p><p><span class="lbl">after:</span> %s</p>'
                % (inline(m.group(1)), inline(m.group(2))))
    return '<p>%s</p>' % inline(s)


def proof(q):
    return ('<details class="proof"><summary>Assay proof</summary><div class="proof-body"><h4>Nearby words (proof of page-read)</h4>'
            '%s<div class="why"><h4>Why rare / valuable</h4><p>%s</p></div></div></details>'
            % (nearby(q.get('Nearby words (proof of page-read)', '')), inline(q.get('Why rare/valuable', ''))))


def meta(q):
    return ('<dl class="meta"><dt>Work</dt><dd>%s</dd><dt>Translator</dt><dd>%s</dd></dl>'
            % (inline(q.get('Work + location', '')), inline(q.get('Translator / edition', ''))))


GEMS = ['ruby', 'sapphire', 'emerald']


def gem_card(q, i):
    u = q.get('Source URL', '')
    g = GEMS[i]
    return ('<article class="card panel gem-card treasure %s" id="treasure-%d" aria-label="Rank %d treasure">'
            '<div class="setting" aria-hidden="true"><div class="gem"></div></div><span class="gem-name">%s</span>'
            '<span class="rank-tag">Rank %s</span><blockquote class="quote" cite="%s"><p>%s</p></blockquote>'
            '<p class="who">%s</p>%s<div class="card-foot">%s%s</div></article>'
            % (g, q['rank'], q['rank'], g.capitalize(), roman(q['rank']), E(u), inline(q.get('Quote', '')),
               inline(q.get('Philosopher', '')), meta(q), src_link(u), proof(q)))


def coin_card(q):
    u = q.get('Source URL', '')
    r = q['rank']
    return ('<article class="card panel coin-card treasure" id="treasure-%d" aria-label="Rank %d treasure">'
            '<div class="head"><div class="coin" title="Rank %d">%s</div><p class="who">%s</p></div>'
            '<blockquote class="quote" cite="%s"><p>%s</p></blockquote>%s<div class="card-foot">%s%s</div></article>'
            % (r, r, r, roman(r), inline(q.get('Philosopher', '')), E(u), inline(q.get('Quote', '')),
               meta(q), src_link(u), proof(q)))


def ledger_li(e):
    kind = e['kind']
    cls = dict(STATUSES).get(kind) or kind.lower().replace(' ', '-')
    extra = ''.join(badge(l, c) for l, c in statuses(e['note']) if l != kind)
    q = '<p class="q">&#8220;%s&#8221;</p>' % E(e['quote']) if e['quote'] else ''
    link = (' &middot; <a href="%s" target="_blank" rel="noopener noreferrer">Source &#8599;</a>' % E(e['url'])) if e['url'] else ''
    return ('<li><div class="seal b-%s" role="note" aria-label="Status: %s">%s</div>%s<div class="entry"><p class="note">%s</p>'
            '%s<p class="attr">%s%s</p></div></li>' % (E(cls), E(kind), E(kind), extra, E(e['note']), q, E(e['attr']), link))


def build(d, mobile=False):
    ranked = sorted(d['ranked'], key=lambda q: q['rank'])
    crown, gold = ranked[:3], ranked[3:]
    hi = roman(gold[-1]['rank']) if gold else ''
    p = []
    vp = ('<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n'
          '<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="mobile-web-app-capable" content="yes">\n'
          '<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n'
          '<meta name="apple-mobile-web-app-title" content="Hoard">\n<meta name="theme-color" content="#121010">\n'
          '<meta name="format-detection" content="telephone=no">\n' + touch_icon_tag() + '\n') if mobile else \
         '<meta name="viewport" content="width=device-width, initial-scale=1">\n'
    p.append('<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n'
             + vp +
             '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:;">\n'
             '<meta name="color-scheme" content="dark">\n'
             + favicon_tag() + '\n'
             '<!-- Generated by build_hoard.py from nifflers-pouch.md. Edit the pouch, then re-run the script. -->\n'
             "<title>Niffler&#x27;s Hoard</title>\n<style>\n" + CSS + ('\n' + MOBILE_CSS if mobile else '') + '\n</style>\n</head>\n<body>\n')
    p.append('<a class="skip" href="#crown-vault">Skip to the treasure</a>\n')
    torch = '<span class="glow"></span><span class="flame"></span><span class="stick"></span>'
    p.append('<header class="gate"><div class="battlements" aria-hidden="true"></div><div class="wall">'
             '<div class="torch left" aria-hidden="true">%s</div><div class="torch right" aria-hidden="true">%s</div>'
             '<div class="arch"><div class="portcullis" aria-hidden="true"></div><div class="crest">The Keep of the Niffler</div>'
             "<h1 class=\"inlay\">Niffler&#x27;s Hoard</h1><p class=\"subtitle\">Rare knowledge. Every coin assayed against its page.</p><div class=\"runes\" aria-hidden=\"true\"></div></div></div></header>\n"
             % (torch, torch))
    if mobile:
        p.append('<main>\n')
    else:
        p.append('<nav class="halls" aria-label="Rooms of the keep"><a href="#crown-vault">The Crown Vault</a><a href="#gold-hall">The Gold Hall</a>'
                 '<a href="#new-finds">The New Finds Tower</a><a href="#gatehouse">The Gatehouse Ledger</a></nav>\n<main>\n')
    p.append('<section class="plaque panel" aria-labelledby="assay-h"><h2 id="assay-h">Assay rule</h2><p class="rule">Every item opened on a written '
             'source page; anything unsourced is melted down.</p><p class="from-pouch">%s</p></section>\n' % inline(d['tagline']))
    p.append('<section class="room" id="crown-vault" aria-labelledby="crown-h"><div class="room-head"><h2 id="crown-h" class="carved">The Crown Vault</h2>'
             '<p>Ranks I&ndash;III &mdash; the ruby, the sapphire, the emerald. Ranked by rarity &times; depth &times; postability.</p></div>'
             '<div class="crown">' + ''.join(gem_card(q, i) for i, q in enumerate(crown)) + '</div></section>\n')
    p.append('<section class="room" id="gold-hall" aria-labelledby="gold-h"><div class="room-head"><h2 id="gold-h" class="carved">The Gold Hall</h2>'
             '<p>Ranks IV&ndash;%s &mdash; struck, weighed, and stacked.</p></div><div class="hall">' % hi
             + ''.join(coin_card(q) for q in gold) + '</div></section>\n')
    finds = ''.join('<article class="find new-find panel"><span class="num" aria-hidden="true">%d</span><div class="badges">%s</div><h3>%s</h3>%s%s</article>'
                    % (f['num'], ''.join(badge(l, c) for l, c in statuses(f['title'])), inline(f['title']),
                       ('<details class="find-body"><summary>Read the find</summary><p>%s</p></details>' if mobile else '<p>%s</p>') % inline(f['text']), src_link(f['url']) if f['url'] else '') for f in d['finds'])
    p.append('<section class="room" id="new-finds" aria-labelledby="finds-h"><div class="room-head"><h2 id="finds-h" class="carved">The New Finds Tower</h2>'
             '<p>%s</p></div><div class="tower">%s</div></section>\n' % (inline(d['finds_intro']), finds))
    tally = ''.join('<div class="count"><span class="n">%d</span><span class="l">%s</span></div>' % (n, E(l)) for l, n in d['tally'])
    melt = ''.join('<li>%s</li>' % inline(x) for x in d['discards'])
    p.append(('<section class="room" id="gatehouse" aria-labelledby="gate-h"><div class="room-head"><h2 id="gate-h" class="carved">The Gatehouse Ledger</h2>'
             '<p>What left the keep, what is held at the gate, and the count of the coffers.</p></div><div class="ledger panel">'
             '<p class="updated">Last updated: <strong>%s</strong></p>'
             + ('<details class="fold"><summary>Handed to Hermes / held</summary><ul class="log">%s</ul></details>'
                '<details class="fold"><summary>Waiting at the gate</summary><ul class="log">%s</ul></details>' if mobile else
                '<h3>Handed to Hermes / held</h3><ul class="log">%s</ul><h3>Waiting at the gate</h3><ul class="log">%s</ul>')
             + '<h3>Verification tally</h3><div class="tally">%s</div>'
             '<details class="melt"><summary>The Melting Pot &mdash; discarded this dig: %d</summary><ul>%s</ul></details></div></section>\n')
             % (E(d['updated']), ''.join(ledger_li(e) for e in d['ledger']), ''.join(ledger_li(e) for e in d['waiting']),
                tally, d['discard_count'], melt))
    tabs = ('<nav class="tabs" aria-label="Rooms of the keep"><a href="#crown-vault"><span class="ic" aria-hidden="true">&#9670;</span>Vault</a>'
            '<a href="#gold-hall"><span class="ic" aria-hidden="true">&#9673;</span>Hall</a><a href="#new-finds"><span class="ic" aria-hidden="true">&#9650;</span>Finds</a>'
            '<a href="#gatehouse"><span class="ic" aria-hidden="true">&#9636;</span>Ledger</a></nav>\n') if mobile else ''
    p.append('</main>\n' + tabs + '<footer>Built from <code>nifflers-pouch.md</code> by <code>build_hoard.py</code>. Nothing unsourced survives the forge.</footer>\n</body>\n</html>\n')
    return ''.join(p)


def verify(d, out, md, mobile=False):
    res = []
    ck = lambda name, ok, extra='': res.append((ok, name + (' - ' + extra if extra and not ok else '')))
    text = html.unescape(re.sub(r'<[^>]+>', '', out))
    raw_un = html.unescape(out)
    ranked = d['ranked']
    ck('parsed %d ranked quotes, ranks contiguous 1..%d' % (len(ranked), len(ranked)),
       len(ranked) >= 3 and sorted(q['rank'] for q in ranked) == list(range(1, len(ranked) + 1)))
    req = ['Quote', 'Philosopher', 'Work + location', 'Translator / edition', 'Source URL', 'Nearby words (proof of page-read)', 'Why rare/valuable']
    miss = ['%d:%s' % (q['rank'], f) for q in ranked for f in req if not q.get(f)]
    ck('every ranked quote has all 7 fields', not miss, ', '.join(miss))
    allq = [plain(q['Quote']) for q in ranked] + [e['quote'] for e in d['ledger'] + d['waiting'] if e['quote']]
    miss = [q[:50] for q in allq if q not in text]
    ck('all %d quotes from md (ranked + ledger + waiting) appear in html' % len(allq), not miss, '; '.join(miss))
    urls = sorted(set(u.rstrip(').,;]>"\'') for u in URL_RE.findall(md)))
    miss = [u for u in urls if u not in raw_un]
    ck('all %d distinct URLs in md appear in html' % len(urls), not miss, ' '.join(miss))
    ck('Crown Vault has 3 gem cards (ruby, sapphire, emerald)', out.count('gem-card treasure') == 3 and all('gem-card treasure ' + g in out for g in GEMS))
    ck('Gold Hall has %d coin cards' % (len(ranked) - 3), out.count('coin-card treasure') == len(ranked) - 3)
    ck('Assay proof panel on every card (%d)' % len(ranked), out.count('<details class="proof">') == len(ranked))
    ck('New Finds Tower has %d finds, each with a source link' % len(d['finds']),
       out.count('class="find new-find panel"') == len(d['finds']) and all(f['url'] for f in d['finds']))
    nk = len(d['ledger']) + len(d['waiting'])
    ck('Gatehouse Ledger shows %d ledger + %d waiting lines' % (len(d['ledger']), len(d['waiting'])), out.count('<div class="seal ') == nk)
    kinds = {}
    for e in d['ledger'] + d['waiting']:
        kinds[e['kind']] = kinds.get(e['kind'], 0) + 1
    ck('ledger kinds parsed: ' + ', '.join('%s=%d' % kv for kv in sorted(kinds.items())), 'SENT' in kinds and 'WAITING' in kinds)
    bad = [e['note'] for e in d['ledger'] + d['waiting'] if re.search(r'\d:\d\d', e['note'])]
    ck('ledger times use periods, not colons', not bad, '; '.join(bad))
    tal = dict(d['tally'])
    actual = {'ranked': len(ranked), 'discard': d['discard_count'], 'finds': len(d['finds'])}
    got = {}
    for l, n in d['tally']:
        k = 'ranked' if 'ranked' in l.lower() else 'discard' if 'discard' in l.lower() else 'finds' if 'find' in l.lower() else l
        got[k] = n
    ck('tally matches parsed entries (ranked %d, discarded %d, finds %d)' % (actual['ranked'], actual['discard'], actual['finds']),
       got == actual, 'tally %r vs parsed %r' % (got, actual))
    ck('discard header count matches discard list', d['discard_count_stated'] == d['discard_count'])
    ck('tally numbers rendered in html', all('<span class="n">%d</span>' % n in out for n in tal.values()) and
       'discarded this dig: %d' % d['discard_count'] in out)
    ck('Last updated shown (%s)' % d['updated'], bool(d['updated']) and ('Last updated: <strong>%s</strong>' % E(d['updated'])) in out)
    nb = sum(len(statuses(f['title'])) for f in d['finds'])
    ck('New Finds status badges parsed from titles (%d)' % nb, out.count('<span class="badge b-') >= nb and nb > 0)
    kr = [e for e in d['ledger'] + d['waiting'] if e['raw'][2:].startswith('KNOWN RESULT')]
    ck('KNOWN RESULT lines render as one badge (%d), no RESULT spill' % len(kr),
       all(e['kind'] == 'KNOWN RESULT' and not e['note'].startswith('RESULT') for e in kr)
       and out.count('<div class="seal b-known"') == len(kr))
    fav = favicon_tag()
    ck('inline PNG favicon in <head> matches icon/hoard-favicon.png', fav in out.split('</head>')[0] and out.count('rel="icon"') == 1)
    out_nf = out.replace(fav, '', 1)
    if mobile:
        out_nf = out_nf.replace(touch_icon_tag(), '', 1)
    ext = re.findall(r'<(?:script|link|img|iframe|object|embed|video|audio|source)\b|\bsrc\s*=|@import|url\(\s*["\']?(?:https?:)?//', out_nf, re.I)
    ck('no external loads (no script/link/img/src/@import/url())', not ext, repr(ext[:5]))
    anchors = re.findall(r'<a\b[^>]*href="(https?://[^"]+)"[^>]*>', out)
    tags = re.findall(r'<a\b[^>]*href="https?://[^"]+"[^>]*>', out)
    ck('all %d outbound links use target=_blank' % len(anchors), all('target="_blank"' in t for t in tags))
    for sid in ('crown-vault', 'gold-hall', 'new-finds', 'gatehouse'):
        ck('section #%s present' % sid, 'id="%s"' % sid in out)
    ck('header gate, nav, tagline and Melting Pot present',
       all(x in out for x in ('<header class="gate">', '<nav class="tabs"' if mobile else '<nav class="halls"', 'class="from-pouch"', '<details class="melt">')))
    if mobile:
        head = out.split('</head>')[0]
        ck('mobile: viewport-fit=cover viewport meta', 'content="width=device-width, initial-scale=1, viewport-fit=cover"' in head)
        ck('mobile: apple web-app metas + theme-color', all(x in head for x in (
            '<meta name="apple-mobile-web-app-capable" content="yes">', '<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">',
            '<meta name="apple-mobile-web-app-title" content="Hoard">', '<meta name="theme-color"')))
        ck('mobile: inline 180x180 apple-touch-icon', touch_icon_tag() in head and out.count('rel="apple-touch-icon"') == 1)
        ck('mobile: safe-area-inset padding for notch and home bar', 'env(safe-area-inset-top)' in out and 'env(safe-area-inset-bottom)' in out)
        tabs = re.search(r'<nav class="tabs"[^>]*>(.*?)</nav>', out)
        ck('mobile: bottom tab bar Vault/Hall/Finds/Ledger and no top nav',
           bool(tabs) and re.findall(r'href="#([\w-]+)"[^>]*>.*?</span>(\w+)</a>', tabs.group(1)) ==
           [('crown-vault', 'Vault'), ('gold-hall', 'Hall'), ('new-finds', 'Finds'), ('gatehouse', 'Ledger')] and '<nav class="halls"' not in out)
        ck('mobile: 44px tap targets (tabs, summaries, source links)', all(x in out for x in (
            'min-height:44px;cursor:pointer', '.source,.log a{display:inline-flex;align-items:center;min-height:44px}', 'min-width:44px')))
        ck('mobile: %d find bodies + ledger lists collapsed in <details>' % len(d['finds']),
           out.count('<details class="find-body">') == len(d['finds']) and out.count('<details class="fold">') == 2)
        ck('mobile: no fixed background-attachment', not re.search(r'background-attachment\s*:\s*fixed|\bfixed\s*,', out))
        ck('mobile: light SVG filters (numOctaves <= 2)', max(int(n) for n in re.findall(r"numOctaves='(\d+)'", MOBILE_CSS)) <= 2)

    t = parse_ledger_line('- SENT 2026-01-01 9.00 AM CT (note: with colon): Author, Work 1:2 (Tr): "A: b: c." https://example.org/a:b')
    ck('parse survives colons in note, attribution, quote and URL',
       t['note'] == '2026-01-01 9.00 AM CT (note: with colon)' and t['attr'] == 'Author, Work 1:2 (Tr)'
       and t['quote'] == 'A: b: c.' and t['url'] == 'https://example.org/a:b')
    tq = parse('# T\nx\nLast updated: 2026-01-01 1.00 PM CT\n## Ranked\n### 1\n**Quote:** Time: the thief: always.\n**Source URL:** https://e.org/x\n')
    ck('ranked field parse keeps colons in quote text', tq['ranked'][0]['Quote'] == 'Time: the thief: always.')
    return res


def main(argv):
    here = os.path.dirname(os.path.abspath(__file__))
    mobile = '--mobile' in argv
    argv = [a for a in argv if a != '--mobile']
    src = argv[1] if len(argv) > 1 else os.path.join(here, 'nifflers-pouch.md')
    dst = argv[2] if len(argv) > 2 else os.path.join(here, 'nifflers-hoard-iphone.html' if mobile else 'nifflers-hoard.html')
    md = open(src, encoding='utf-8').read()
    d = parse(md)
    out = build(d, mobile)
    with open(dst, 'w', encoding='utf-8') as f:
        f.write(out)
    res = verify(d, out, md, mobile)
    for ok, name in res:
        print('[%s] %s' % ('PASS' if ok else 'FAIL', name))
    fails = sum(1 for ok, _ in res if not ok)
    print('%d checks, %d failed. Wrote %s (%d bytes)' % (len(res), fails, dst, len(out.encode('utf-8'))))
    return 1 if fails else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
